create temporary view dwm_homepage_user_item_${grass_region_without_quote} as
select
    user_id
    ,case
        when card_type in ('food_item', 'food_collection') then 'food'
        when card_type in ('insurance_card') then 'insurance'
        when card_type in ('shopeepay_near_me') then 'local service'
        when card_type in ('digital_product') then 'DP'
        when card_type in ('banner') then 'banner'
        when card_type in ('campaign') then 'campaign'
        else coalesce(get_dd_cardtype(object),get_dd_cardtype(source1_object), get_dd_cardtype(source2_object), object)
    end as card_type
    ,case
        when is_ads = true then 1
        else 0
    end as is_ads
    ,sum(imp_cnt) as imp_cnt
    ,sum(click_cnt) as click_cnt
    ,0 as order_cnt
    ,0 as gmv
    ,0 as pc2_gmv
    ,max(case when feature_detail like 'home-daily_discover-%' then location else 0 end) as location
    ,0 as ppv_cnt
from srdi_mart.dwm_sr_data_warehouse_homepage_user_item
where
    local_date = ${local_date}
    and grass_region = ${grass_region}
    and feature_detail like 'home-daily_discover-%'
group by 1, 2, 3
having card_type is not null
;

