    ,sum(case when (object in ('shopeepay_near_me') or source1_object in ('shopeepay_near_me') or source2_object in ('shopeepay_near_me'))
                   or (object in ('digital_product') or source1_object in ('digital_product') or source2_object in ('digital_product')) then 0 else gmv end) as gmv
    ,sum(pc2_gmv) as pc2_gmv
    ,sum(ppv_cnt) as ppv_cnt
    ,max(case when feature_detail like 'home-daily_discover-%' then location else 0 end) as location
from srdi_mart.dwm_sr_data_warehouse_homepage_user_item
where
