create temporary view dwm_dd_others_user_location_${grass_region_without_quote} as
select
    user_id
    ,case
        when feature_detail = 'home-daily_discover-food' then 'food'
        when feature_detail = 'home-daily_discover-insurance' then 'insurance'
        when feature_detail = 'home-daily_discover-banner' then 'banner'
        when feature_detail = 'home-daily_discover-campaign' then 'campaign'
        when feature_detail = 'home-daily_discover-shopeepay_near_me' then 'local service'
        when feature_detail = 'home-daily_discover-digital_product' then 'DP'
        else null
