-- vv
create temporary view vv_data_${grass_region_without_quote} as
select
    grass_region
    ,grass_date as local_date
    ,user_id
    ,case
        when sv_source_page in ('iaa_dd_mix_item') then 'item_mix_feed_card'
        when sv_source_page in ('iaa_dd_video_card') then 'video'
    end as card_type
    ,case when coalesce(is_item_ads,0) = 1 then 1 else 0 end as is_ads
    ,sum(video_play_cnt_ntl_1d) as vv
from video.video_mart_dws_external_dd_mixfeed_ssecid_user_1d
where
    grass_region = ${grass_region}
    and grass_date = ${local_date}
    and current_page in ('mix_feed_page', 'common_video_feed_page','dd_video_new_landing_page')
    and sv_source_page in ('iaa_dd_mix_item', 'iaa_dd_video_card')
group by 1, 2, 3, 4, 5
;

--sql_divide_splitter--
--internal scroll depth
create temporary view internal_scroll_depth_${grass_region_without_quote} as
select
    user_id
    ,case
        when get_json_object(data, '$.position.current_page') in ('mix_feed_page', 'common_video_feed_page','dd_video_new_landing_page')
            and get_json_object(data, '$.params.sv_source_page') = 'iaa_dd_video_card'
            then 'video'
        when get_json_object(data, '$.position.current_page') in ('mix_feed_page')
            and get_json_object(data, '$.params.sv_source_page') = 'iaa_dd_mix_item'
            then 'item_mix_feed_card'
    end as card_type
    ,case when coalesce(get_json_object(data,'$.params.is_ads'),'') = 'true' then 1 else 0 end as is_ads
    ,max(cast(get_json_object(data, '$.params.index') as int)) as internal_scroll_depth
from video.video_mart_dwd_external_dd_mixfeed_traffic_hi
where
    grass_region = ${grass_region}
    and grass_date = ${local_date}
    and page_type = 'video'
    and operation = 'impression'
    and target_type = 'video_product_impression'
    and (
        (
            get_json_object(data, '$.position.current_page') in ('mix_feed_page', 'common_video_feed_page','dd_video_new_landing_page')
            and get_json_object(data, '$.params.sv_source_page') = 'iaa_dd_video_card'
        )
        or (
            get_json_object(data, '$.position.current_page') = 'mix_feed_page'
            and get_json_object(data, '$.params.sv_source_page') = 'iaa_dd_mix_item'
        )
    )
group by 1, 2 ,3
;

