create temporary view minippv_data_base_${grass_region_without_quote} as
select  grass_region
        ,local_date as grass_date
        ,user_id
        ,coalesce(get_dd_cardtype(source1_object), source1_object) as card_type
        ,sum(item_impr_organic_cnt_1d) as minippv_organic
        ,sum(item_impr_ads_cnt_1d) as minippv_ads
from    traffic_omni_oa.dws_business_line_sales_funnel_metrics_1d__reg_sensitive_live
where   grass_region = ${grass_region}
  and   local_date = ${local_date}
  and   (
                source1_business_line = 'Homepage'
            and source1_module = 'Daily Discover'
        )
group by 1, 2, 3, 4
;

