INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_homepage_user_cardtype_ad_1d
partition (grass_region = ${grass_region}, local_date = ${local_date})
select
    T1.user_id
    ,T2.user_purchase_type
    ,T2.platform
    ,T2.app_version_prefix
    ,T1.card_type
    ,T1.is_ads
    ,T1.imp_cnt
    ,T1.click_cnt
    ,T1.order_cnt
    ,T1.gmv
    ,T1.pc2_gmv
    ,T1.location
    ,T1.ppv_cnt
    ,T1.minippv_cnt
    ,T1.vv
    ,T1.self_duration
    ,T1.landing_page_duration
    ,T1.pdp_page_duration
    ,T1.internal_scroll_depth
from
    union_data_result_${grass_region_without_quote} as T1
    left join dim_user_${grass_region_without_quote} as T2
    on T1.user_id = T2.user_id
